      (is (= :vector-slice-work-limit (:reason (check established (dec (:work-count measured))))))
      (when (< (count value) 1024)
        (let [context {:ordering-core core :lookup-nodes nodes :lookup-forms (vec (vals forms))
                       :lookup-bindings (vec (vals bindings))
                       :shape-call-products {:module (:module core) :calls (:calls core) :call-edges (:call-edges core)}}
              inferred (invoke-c7 'sh08-ft-infer-acyclic-with-context
                         [(:nodes core) nodes (:lexical-bindings core) [] (:calls core) (:call-edges core) {} {} 10 context])]
          (is (= :converged (:convergence-status inferred)))
          (is (= [] (:diagnostics inferred)))
          (is (= (:type result) (get-in inferred [:type-table :slice-call]) (get-in inferred [:type-table :slice-let])))))
      (doseq [path [[:bounds-proof :receiver :record :binding-scope-id]
                    [:bounds-proof :receiver :reference :attributes :symbol]
                    [:bounds-proof :receiver :origin :kind] [:bounds-proof :result-count]]]
        (is (= :rejected (:status (check (assoc-in established (into [:slice-operator] path) :forged) 65536)))))))
  (doseq [[value start end] [["abc" -1 1] ["abc" 2 1] ["abc" 0 4]
                            [[65 66 67] -1 1] [[65 66 67] 2 1] [[65 66 67] 0 4]
                            ["\u0100" 0 1] [(vec (range 1025)) 0 1]]]
    (let [{:keys [core node call edge nodes bindings types forms]} (let-vector-slice-input value start end)]
      (is (= :rejected (:status (invoke-c7 'sh08-vsl-derive [core node call edge nodes bindings types forms 65536]))))))
  (let [transfer (ns-resolve 'gravity.self-hosting.sh08-function-call-type-test 'vector-slice-transfer-input)]
    (doseq [positions [0 1 2 [0 1 2]]]
      (let [{:keys [core node call edge nodes bindings types forms]}
            (let-vector-slice-input (transfer "sha256:abcd" 20 1 positions) 20 1)
            result (invoke-c7 'sh08-vsl-derive [core node call edge nodes bindings types forms 65536])
            descriptor (:descriptor result)]
        (is (= :accepted (:status result)) (pr-str result))
        (is (= :gravity.type/never (:type result)))
        (is (= [] (:direct-effects descriptor)))
        (is (= [nil nil nil] ((juxt :input-count :result-count :selected-types) (:bounds-proof descriptor))))
        (when (contains? #{1 2} positions)
          (is (= :rejected (:status (invoke-c7 'sh08-vsl-derive
                                     [core node call edge nodes bindings types (assoc-in forms [:slice-let-name :value] 'substitute) 65536]))))))))
  (let [base (update (let-vector-slice-input [65 66 67] 1 2) :forms #(into clojure.lang.PersistentHashMap/EMPTY %))
        derive (fn [input] (invoke-c7 'sh08-vsl-derive [(:core input) (:node input) (:call input) (:edge input)
                                                      (:nodes input) (:bindings input) (:types input) (:forms input) 65536]))]
    (is (= :accepted (:status (derive base))))
    (doseq [mutate [#(assoc-in % [:core :lexical-bindings] [])
                    #(update-in % [:core :lexical-bindings] conj (first (get-in % [:core :lexical-bindings])))
                    #(assoc-in % [:core :lexical-bindings 0 :initializer-node-id] :slice-start)
                    #(assoc-in % [:core :lexical-bindings 0 :mutability] :mutable)
                    #(assoc-in % [:core :lexical-bindings 0 :binding-scope-id] :sibling)
                    #(assoc-in % [:core :mutations] [{:target-binding-id :slice-let-binding}])
                    #(assoc-in % [:bindings :slice-let-binding :kind] :parameter)
                    #(assoc-in % [:bindings :slice-let-binding :name] 'substitute)
                    #(assoc-in % [:nodes :slice-ref :binding-context] :slice-let-outer)
                    #(assoc-in % [:nodes :slice-let :children] [:slice-call :call])
                    #(assoc-in % [:nodes :slice-let :evaluation :order] [])
                    #(assoc-in % [:nodes :slice-let :attributes :body-count] 2)
                    #(assoc-in % [:forms :slice-ref :scope-id] :sibling)
                    #(assoc-in % [:forms :slice-let-name :value] 'substitute)
                    #(assoc-in % [:forms :slice-call :parent-form-id] :sibling)
                    #(assoc-in % [:forms :call :parent-form-id] :slice-let)
                    #(assoc-in % [:forms :slice-let-bindings :child-form-ids] [:call :slice-let-name])
                    #(assoc-in % [:types :slice-ref :element-types] [:gravity.type/string])]]
      (is (= :rejected (:status (derive (mutate base))))))
    (let [callbacks (atom 0) opaque (proxy [Object] []
                                    (hashCode [] (swap! callbacks inc) (throw (AssertionError. "let slice hash")))
                                    (equals [_] (swap! callbacks inc) (throw (AssertionError. "let slice equality")))
                                    (toString [] (swap! callbacks inc) (throw (AssertionError. "let slice formatting"))))]
      (doseq [path [[:core :lexical-bindings 0 :definition-form-id] [:nodes :slice-let :source :form-id]
                    [:nodes :slice-let :node-id] [:forms :slice-let-op :form-id]
                    [:forms :slice-let-name :syntax-id] [:bindings :slice-let-binding :name]
                    [:forms :slice-ref :value] [:nodes :slice-ref :source :form-id]]]
        (is (= :rejected (:status (derive (assoc-in base path opaque))))))
      (is (= 0 @callbacks)))))

(defn- vector-slice-derived [input budget]
  (invoke-c7 'sh08-vsl-derive [(:core input) (:node input) (:call input) (:edge input)
                              (:nodes input) (:bindings input) (:types input) (:forms input) budget]))

(defn- vector-slice-transfer-input [text start end positions]
  (let [positions (if (sequential? positions) (set positions) #{positions})
        input (vector-slice-input (if (positions 0) (literal-string-vector-transfer-input) text) start end)
        input (reduce (fn [input position]
                        (let [id (if (= position 1) :slice-start :slice-end)
                              op (keyword (str "slice-throw-op-" position)) payload (keyword (str "slice-payload-" position))
                              form (get-in input [:forms id]) source (get-in input [:nodes id :source])
                              transfer (assoc (get-in input [:nodes id]) :core-form :throw :children [payload]
                                              :attributes {} :evaluation {:order [{:index 0 :core-node-id payload}]})
                              value "original slice transfer"
                              payload-node {:node-id payload :core-form :literal :children [] :resolved-binding-ids []
                                            :attributes {:literal-kind :string :value value}
                                            :source (assoc source :form-id payload :syntax-id payload) :evaluation {:kind :value :order []}}]
                          (-> input (assoc-in [:nodes id] transfer) (assoc-in [:nodes payload] payload-node)
                              (assoc-in [:types id] :gravity.type/never) (assoc-in [:types payload] :gravity.type/string)
                              (assoc-in [:forms id] (assoc form :kind :list :value (list 'throw value) :child-form-ids [op payload]))
                              (assoc-in [:forms op] (assoc form :form-id op :syntax-id op :parent-form-id id :kind :symbol :value 'throw :child-form-ids []))
                              (assoc-in [:forms payload] (assoc form :form-id payload :syntax-id payload :parent-form-id id :kind :string :value value :child-form-ids []))
                              (update-in [:core :nodes] #(conj (mapv (fn [n] (if (= id (:node-id n)) transfer n)) %) payload-node)))))
                      input (filter #{1 2} positions))]
    (vector-slice-established input)))

(defn- sha-suffix-character-membership-input [text start end positions]
  ;; Existing owners composed as normalized DATA; source admission is separate.
  (let [base (if (nil? positions) (vector-slice-input text start end) (vector-slice-transfer-input text start end positions))
        source (fn [id] {:form-id id :syntax-id id :semantic-span nil :origin-chain [] :generated-origin nil})
        form (fn [id kind value parent children]
               {:form-id id :syntax-id id :source-span nil :origin-chain [] :generated-origin nil
                :kind kind :value value :parent-form-id parent :child-form-ids children})
        values (vec "0123456789abcdef") ids (mapv #(keyword (str "suffix-hex-" %)) (range 16))
        characters (mapv (fn [id value] {:node-id id :core-form :literal :children [] :resolved-binding-ids []
                                        :source (source id) :attributes {:literal-kind :character :value value}
                                        :evaluation {:kind :value :order []}}) ids values)
        set-node {:node-id :suffix-hex-set :core-form :collection-literal :children ids :resolved-binding-ids []
                  :source (source :suffix-hex-set) :attributes {:literal-kind :set :element-count 16 :source-value (set values)}
                  :evaluation {:kind :left-to-right :order (mapv #(hash-map :index %1 :core-node-id %2) (range) ids)}}
        added (conj characters set-node)
        base (-> base (update-in [:core :nodes] into added)
                 (update :nodes into (map (juxt :node-id identity) added))
                 (update :forms into (map (fn [id value] [id (form id :character value :suffix-hex-set [])]) ids values))
                 (assoc-in [:forms :suffix-hex-set] (form :suffix-hex-set :set (set values) nil ids))
                 (update :types merge (zipmap ids (repeat :gravity.type/character))
                         {:suffix-hex-set {:kind :gravity.type/set :shape :literal :element-types (vec (repeat 16 :gravity.type/character))}}))
        append-call
        (fn [input id operation args]
          (let [op (keyword (str (name id) "-operator")) bid (keyword (str (name id) "-binding"))
                definition (keyword (str (name id) "-definition")) children (into [op] args)
                binding (assoc (get-in input [:bindings :ordering-binding]) :binding-id bid :name operation :definition-syntax-id definition)
                operator {:node-id op :core-form :reference :children [] :resolved-binding-ids [bid]
                          :source (source op) :attributes {:symbol operation :position :operator :binding-id bid :binding-class :core
                                                         :definition-syntax-id definition} :evaluation {:order []}}
                node {:node-id id :core-form :call :children children :resolved-binding-ids [bid] :source (source id)
                      :attributes {:operator-child-index 0 :argument-count (count args) :argument-child-indexes (vec (range 1 (count children)))
                                   :evaluation-order :operator-then-arguments :dispatch :resolved-symbol-call}
                      :evaluation {:owner-function-syntax-id nil :kind :operator-then-arguments
                                   :order (mapv #(hash-map :index %1 :core-node-id %2) (range) children)}}
                call {:core-node-id id :operator-node-id op :operator-binding-id bid :argument-node-ids args
                      :ordered-evaluation-node-ids children :evaluation-order :operator-then-arguments :result-policy :call-result}
                edge {:ordinal (count (get-in input [:core :calls])) :call-core-node-id id
                      :caller-function-syntax-id nil :caller-function-core-node-id nil :callee-binding-id bid
                      :callee-definition-syntax-id definition :callee-function-syntax-id nil :callee-function-core-node-id nil
                      :argument-core-node-ids args :ordered-evaluation-node-ids children
                      :evaluation-order :operator-then-arguments :classification :nonlocal-or-nonfunction}]
            (-> input (assoc :node node :call call :edge edge)
                (update :nodes assoc op operator id node) (assoc-in [:bindings bid] binding)
                (update-in [:core :nodes] into [operator node]) (update-in [:core :calls] conj call) (update-in [:core :call-edges] conj edge)
                (assoc-in [:forms op] (form op :symbol operation id [])) (assoc-in [:forms id] (form id :list id nil children))
                (update :forms #(reduce (fn [forms child] (assoc-in forms [child :parent-form-id] id)) % args)))))
        input (-> base (append-call :suffix-first 'first [:slice-call])
                  (append-call :suffix-member 'contains? [:suffix-hex-set :suffix-first]))]
    (assoc input :binding-types (:types input)
                 :products {:module (:module input) :calls (get-in input [:core :calls]) :call-edges (get-in input [:core :call-edges])})))

(defn- sha-suffix-character-membership-established [input]
  (let [input (vector-slice-established input) {:keys [core nodes bindings forms]} input
        calls (:calls core) edges (:call-edges core)
        derive (fn [name index types]
                 (let [call (get calls index)]
                   (invoke-c7 name [core (nodes (:core-node-id call)) call (get edges index) nodes bindings types forms 65536])))
        retain (fn [types index result] (let [call (get calls index)]
                                         (assoc types (:operator-node-id call) (:descriptor result)
                                                      (:core-node-id call) (:type result :gravity.type/unknown))))
        slice (derive 'sh08-vsl-derive 1 (:types input)) types (retain (:types input) 1 slice)
        first-result (derive 'sh08-lq-derive 2 types) types (retain types 2 first-result)
        membership (when (= :accepted (:status first-result)) (derive 'sh08-ksm-derive 3 types))]
    (assoc input :slice slice :first-result first-result :membership membership
                 :types (if membership (retain types 3 membership) types))))

(deftest sh08-sha-suffix-character-membership-development-kernel
  (let [text "sha256:0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef"
        wrong (str (subs text 0 7) "g" (subs text 8))]
    (doseq [[value positions] [[text nil] [wrong nil] [text 0] [text 1] [text 2]]]
      (let [raw (sha-suffix-character-membership-input value 7 71 positions)
            {:keys [core nodes forms bindings child slice first-result membership]} (sha-suffix-character-membership-established raw)
            descriptor (:descriptor membership)]
        (is (= :accepted (:status child) (:status slice) (:status first-result) (:status membership)))
        (is (= (if (nil? positions) :gravity.type/bool :gravity.type/never) (:type membership)))
        (is (= :gravity.type/applied-character-set-contains (:kind descriptor)))
        (is (= [] (:direct-effects descriptor) (:latent-effects descriptor)))
        (is (= (if (nil? positions) :gravity.type/applied-vector-first :gravity.type/applied-list-query)
               (get-in first-result [:descriptor :kind])))
        (when (nil? positions)
          (is (= [64 0 :gravity.type/character]
                 ((juxt :vector-length :selected-index :selected-type) (get-in first-result [:descriptor :bounds-proof]))))
          (let [context {:ordering-core core :lookup-nodes nodes :lookup-forms (vec (vals forms))
                         :lookup-bindings (vec (vals bindings)) :shape-call-products (:products raw)}
                inferred (invoke-c7 'sh08-ft-infer-acyclic-with-context
                           [(:nodes core) nodes [] [] (:calls core) (:call-edges core) {} (:binding-types raw) 10 context])]
            (is (= :converged (:convergence-status inferred)))
            (is (= [] (:diagnostics inferred)))
            (is (= :gravity.type/bool (get-in inferred [:type-table :suffix-member])))
            (is (= #{:sh08-string-character-vector-v1 :sh08-vector-slice-v1 :sh08-vector-first-v1 :sh08-character-set-contains-v1}
                   (set (map :producer-rule (:constraints inferred)))))))))
    (let [raw (sha-suffix-character-membership-input text 71 71 nil)
          {:keys [child slice first-result membership]} (sha-suffix-character-membership-established raw)]
      (is (= :accepted (:status child) (:status slice)))
      (is (= 0 (get-in slice [:descriptor :bounds-proof :result-count])))
      (is (= :rejected (:status first-result)))
      (is (= ["C7-ANNOTATION" :vector-first-nonempty-complete-positional-type-required]
             ((juxt :rule :reason) first-result)))
      (is (= :established-list-and-available-element-types (:expected first-result)))
      (is (= [{:kind :gravity.type/vector :shape :literal :element-types []}] (:actual first-result)))
      (is (nil? membership)))))

(defn- sha-prefix-comparison-input [text expected positions]
  ;; Composition of existing owners in normalized DATA, not source admission.
  (let [inner (if (nil? positions) (vector-slice-input text 0 7) (vector-slice-transfer-input text 20 1 positions))
        values (vec expected) ids (mapv #(keyword (str "prefix-character-" %)) (range (count values)))
        source (fn [id] {:form-id id :syntax-id id :semantic-span nil :origin-chain [] :generated-origin nil})
        form (fn [id kind value parent children]
               {:form-id id :syntax-id id :source-span nil :origin-chain [] :generated-origin nil
                :kind kind :value value :parent-form-id parent :child-form-ids children})
        binding (assoc (get-in inner [:bindings :slice-binding]) :binding-id :prefix-binding :name '=
                       :definition-syntax-id :prefix-definition)
        operator {:node-id :prefix-operator :core-form :reference :children [] :resolved-binding-ids [:prefix-binding]
                  :attributes {:symbol '= :position :operator :binding-id :prefix-binding :binding-class :core
                               :definition-syntax-id :prefix-definition} :source (source :prefix-operator) :evaluation {:order []}}
        characters (mapv (fn [id value] {:node-id id :core-form :literal :children [] :resolved-binding-ids []
                                        :source (source id) :attributes {:literal-kind :character :value value}
                                        :evaluation {:kind :value :order []}}) ids values)
        expected-node {:node-id :prefix-expected :core-form :collection-literal :children ids :resolved-binding-ids []
                       :source (source :prefix-expected)
                       :attributes {:literal-kind :vector :element-count (count ids) :source-value values}
                       :evaluation {:kind :left-to-right :order (mapv #(hash-map :index %1 :core-node-id %2) (range) ids)}}
        children [:prefix-operator :slice-call :prefix-expected]
        node {:node-id :prefix-call :core-form :call :children children :resolved-binding-ids [:prefix-binding]
              :attributes {:operator-child-index 0 :argument-count 2 :argument-child-indexes [1 2]
                           :evaluation-order :operator-then-arguments :dispatch :resolved-symbol-call}
              :source (source :prefix-call) :evaluation {:owner-function-syntax-id nil :kind :operator-then-arguments
                                                        :order (mapv #(hash-map :index %1 :core-node-id %2) (range) children)}}
        call {:core-node-id :prefix-call :operator-node-id :prefix-operator :operator-binding-id :prefix-binding
              :argument-node-ids [:slice-call :prefix-expected] :ordered-evaluation-node-ids children
              :evaluation-order :operator-then-arguments :result-policy :call-result}
        edge {:ordinal 2 :call-core-node-id :prefix-call :caller-function-syntax-id nil :caller-function-core-node-id nil
              :callee-binding-id :prefix-binding :callee-definition-syntax-id :prefix-definition
              :callee-function-syntax-id nil :callee-function-core-node-id nil
              :argument-core-node-ids [:slice-call :prefix-expected] :ordered-evaluation-node-ids children
              :evaluation-order :operator-then-arguments :classification :nonlocal-or-nonfunction}
        added (into [operator] (concat characters [expected-node node])) node-list (into (get-in inner [:core :nodes]) added)
        core (-> (:core inner) (assoc :nodes node-list) (update :calls conj call) (update :call-edges conj edge))
        forms (-> (:forms inner) (assoc-in [:slice-call :parent-form-id] :prefix-call)
                  (assoc :prefix-operator (form :prefix-operator :symbol '= :prefix-call [])
                         :prefix-expected (form :prefix-expected :vector values :prefix-call ids)
                         :prefix-call (form :prefix-call :list :prefix-call nil children))
                  (into (map (fn [id value] [id (form id :character value :prefix-expected [])]) ids values)))
        types (merge (:types inner) (zipmap ids (repeat :gravity.type/character))
                     {:prefix-expected {:kind :gravity.type/vector :shape :literal :element-types (vec (repeat (count ids) :gravity.type/character))}})]
    {:module (:module inner) :core core :node node :call call :edge edge :nodes (into {} (map (juxt :node-id identity) node-list))
     :bindings (assoc (:bindings inner) :prefix-binding binding) :types types :forms forms :inner inner
     :binding-types types :products {:calls (:calls core) :call-edges (:call-edges core) :module (:module inner)}}))

(defn- sha-prefix-comparison-established [input]
  (let [input (vector-slice-established input) {:keys [core nodes bindings forms node call edge]} input
        slice-call (second (:calls core)) slice-edge (second (:call-edges core))
        slice (invoke-c7 'sh08-vsl-derive [core (nodes :slice-call) slice-call slice-edge nodes bindings (:types input) forms 65536])
        types (assoc (:types input) :slice-operator (:descriptor slice) :slice-call (:type slice))
        comparison (invoke-c7 'sh08-ve-derive [core node call edge nodes bindings types forms 65536])]
    (assoc input :slice slice :comparison comparison
                 :types (assoc types :prefix-operator (:descriptor comparison) :prefix-call (:type comparison)))))

(defn- let-vector-count-slice-input
  ([text start] (let-vector-count-slice-input text start nil))
  ([text start position]
  ;; Two distinct local occurrences; count observes the same immutable Vector.
  (let [value (if (nil? position) text (vector-slice-transfer-input text start (count text) position))
        base (let-vector-slice-input value start (count text))
        body :slice-let-body op :slice-count-operator ref :slice-count-reference
        bid :slice-count-binding definition :slice-count-definition
        source #(hash-map :form-id % :syntax-id % :semantic-span nil :origin-chain [] :generated-origin nil)
        binding (assoc (get-in base [:bindings :slice-binding])
                       :binding-id bid :name 'count :definition-syntax-id definition)
        operator {:node-id op :core-form :reference :children [] :resolved-binding-ids [bid]
                  :source (source op) :binding-context body
                  :attributes {:symbol 'count :position :operator :binding-id bid :binding-class :core
                               :definition-syntax-id definition}
                  :evaluation {:kind :value :order []}}
        reference (-> (get-in base [:nodes :slice-ref])
                      (assoc :node-id ref :source (source ref)))
        children [op ref]
        node {:node-id :slice-end :core-form :call :children children :resolved-binding-ids [bid]
              :source (source :slice-end) :binding-context body
              :attributes {:operator-child-index 0 :argument-count 1 :argument-child-indexes [1]
                           :evaluation-order :operator-then-arguments :dispatch :resolved-symbol-call}
              :evaluation {:kind :operator-then-arguments
                           :order [{:index 0 :core-node-id op} {:index 1 :core-node-id ref}]}}
        call {:core-node-id :slice-end :operator-node-id op :operator-binding-id bid
              :argument-node-ids [ref] :ordered-evaluation-node-ids children
              :evaluation-order :operator-then-arguments :result-policy :call-result}
        ordinal (dec (count (get-in base [:core :calls])))
        edge {:ordinal ordinal :call-core-node-id :slice-end :caller-function-syntax-id nil :caller-function-core-node-id nil
              :callee-binding-id bid :callee-definition-syntax-id definition
              :callee-function-syntax-id nil :callee-function-core-node-id nil
              :argument-core-node-ids [ref] :ordered-evaluation-node-ids children
              :evaluation-order :operator-then-arguments :classification :nonlocal-or-nonfunction}
        nodes (into {} (map (fn [[id value]] [id (assoc-in value [:evaluation :region] :module-initialization)]))
                    (assoc (:nodes base) op operator ref reference :slice-end node))
        node-list (letfn [(walk [id] (conj (vec (mapcat walk (:children (nodes id)))) (nodes id)))]
                    (vec (walk :slice-let)))
        calls (vec (concat (butlast (get-in base [:core :calls])) [call (:call base)]))
        edges (vec (concat (butlast (get-in base [:core :call-edges]))
                           [edge (assoc (:edge base) :ordinal (inc ordinal))]))
        form (fn [id kind value parent children]
               {:form-id id :syntax-id id :source-span nil :origin-chain [] :generated-origin nil
                :scope-id body :kind kind :value value :parent-form-id parent :child-form-ids children})
        forms (assoc (:forms base)
                     :slice-end (form :slice-end :list '(count characters) :slice-call children)
                     op (form op :symbol 'count :slice-end [])
                     ref (form ref :symbol 'characters :slice-end []))
        core (assoc (:core base) :nodes node-list :calls calls :call-edges edges)
        input (assoc base :core core :nodes nodes :forms forms :node (nodes :slice-call)
                     :edge (last edges) :bindings (assoc (:bindings base) bid binding))
        input (if (:child base) (vector-slice-established input) input)
        types (assoc (:types input) ref (get-in input [:types :slice-ref]))
        count-result (invoke-c7 'sh08-cq-derive
                               [core (nodes :slice-end) call edge nodes (:bindings input) types forms 65536])]
    (assoc input :count-result count-result
           :types (assoc types op (:descriptor count-result) :slice-end (:type count-result))
           :products {:module (:module core) :calls calls :call-edges edges}))))

(defn- parameter-vector-count-slice-input
  ([text start] (parameter-vector-count-slice-input text start nil))
  ([text start position]
  ;; Conditional normalized typing context; whole-product tests establish it.
  (let [base (let-vector-count-slice-input text start position)
        owner :parameter-function scope :slice-let-body
        source #(hash-map :form-id % :syntax-id % :semantic-span nil :origin-chain [] :generated-origin nil)
        form (fn [id kind value parent children]
               {:form-id id :syntax-id id :source-span nil :origin-chain [] :generated-origin nil
                :scope-id scope :kind kind :value value :parent-form-id parent :child-form-ids children})
        record {:function-syntax-id owner :function-form-id owner :function-core-node-id :parameter-fn
                :body-core-node-id :slice-call :parameter-binding-ids [:slice-let-binding] :fixed-arity 1
                :definition-kind :named-top-level :definition-binding-id :parameter-definition-binding
                :definition-core-node-id :parameter-definition :definition-name 'tail-characters}
        binding (assoc (get-in base [:bindings :slice-let-binding]) :definition-syntax-id :parameter-name
                       :scope-id scope :mutability :immutable)
        fn-node {:node-id :parameter-fn :core-form :fn :children [:slice-call] :source (source owner)
                 :resolved-binding-ids [:slice-let-binding] :binding-context :slice-let-outer
                 :attributes {:parameters ['characters] :parameter-form-id :parameter-vector
                              :parameter-syntax-id :parameter-vector :fixed-arity 1}
                 :evaluation {:kind :function-creation :order []
                              :region :module-initialization :owner-function-syntax-id nil}}
        ids (letfn [(visit [id] (conj (vec (mapcat visit (get-in base [:nodes id :children]))) id))]
              (visit :slice-call))
        nodes (into {} (map (fn [id]
                             [id (-> (get-in base [:nodes id])
                                     (assoc-in [:evaluation :region] :function-body)
                                     (assoc-in [:evaluation :owner-function-syntax-id] owner))]) ids))
        nodes (reduce (fn [out id] (assoc-in out [id :attributes :definition-syntax-id] :parameter-name))
                      nodes [:slice-ref :slice-count-reference])
        nodes (assoc nodes :parameter-fn fn-node)
        forms (-> (select-keys (:forms base) ids)
                  (assoc-in [:slice-call :parent-form-id] owner)
                  (assoc owner (form owner :list (list 'fn ['characters] (list 'subvec 'characters start '(count characters)))
                                     :parameter-definition [:parameter-fn-operator :parameter-vector :slice-call])
                         :parameter-fn-operator (form :parameter-fn-operator :symbol 'fn owner [])
                         :parameter-vector (form :parameter-vector :vector ['characters] owner [:parameter-name])
                         :parameter-name (form :parameter-name :symbol 'characters :parameter-vector [])))
        calls (vec (take-last 2 (get-in base [:core :calls])))
        edges (mapv (fn [ordinal edge] (assoc edge :ordinal ordinal :caller-function-syntax-id owner
                                                 :caller-function-core-node-id :parameter-fn))
                    (range) (take-last 2 (get-in base [:core :call-edges])))
        core (assoc (:core base) :nodes (mapv nodes (conj ids :parameter-fn)) :function-records [record]
                    :lexical-bindings [] :calls calls :call-edges edges :mutations [])
        bindings (assoc (:bindings base) :slice-let-binding binding)
        type (get-in base [:types :slice-ref])
        function (assoc (invoke-c7 'sh08-ft-function-type-skeleton [record (:module core)])
                        :parameters [{:binding-id :slice-let-binding :type type}])
        types (assoc (select-keys (:types base) ids) :parameter-fn function)
        cq (invoke-c7 'sh08-cq-derive [core (nodes :slice-end) (first calls) (first edges) nodes bindings types forms 65536])
        types (assoc types :slice-count-operator (:descriptor cq) :slice-end (:type cq))]
    (assoc base :core core :nodes nodes :node (nodes :slice-call) :call (last calls) :edge (last edges)
           :forms forms :bindings bindings :types types :record record :function function :count-result cq
           :products {:module (:module core) :calls calls :call-edges edges}))))

(defn- parameter-vector-count-slice-caller-input [text start]
  ;; The parameter premise is inferred from an ordinary caller, with no seeds.
  (let [base (parameter-vector-count-slice-input text start)
        argument (literal-string-vector-input text) owner :parameter-caller scope :parameter-caller-scope
        source #(hash-map :form-id % :syntax-id % :semantic-span nil :origin-chain [] :generated-origin nil)
        form (fn [id kind value parent children]
               {:form-id id :syntax-id id :source-span nil :origin-chain [] :generated-origin nil
                :scope-id scope :kind kind :value value :parent-form-id parent :child-form-ids children})
        record (assoc (:record base) :ordinal 0)
        caller {:ordinal 1 :function-syntax-id owner :function-form-id owner :function-core-node-id :parameter-caller-fn
                :body-core-node-id :parameter-entry :parameter-binding-ids [] :fixed-arity 0
                :definition-kind :named-top-level :definition-binding-id :parameter-caller-binding
                :definition-core-node-id :parameter-caller-definition :definition-name 'call-tail}
        entry-children [:parameter-entry-operator :call]
        entry-op {:node-id :parameter-entry-operator :core-form :reference :children []
                  :resolved-binding-ids [:parameter-definition-binding] :source (source :parameter-entry-operator)
                  :binding-context scope :attributes {:symbol 'tail-characters :position :operator :binding-id :parameter-definition-binding
                                                     :binding-class :namespace :definition-syntax-id :parameter-definition-name}
                  :evaluation {:kind :value :order [] :region :function-body :owner-function-syntax-id owner}}
        entry {:node-id :parameter-entry :core-form :call :children entry-children :resolved-binding-ids [:parameter-definition-binding]
               :source (source :parameter-entry) :binding-context scope
               :attributes {:operator-child-index 0 :argument-count 1 :argument-child-indexes [1]
                            :evaluation-order :operator-then-arguments :dispatch :resolved-symbol-call}
               :evaluation {:kind :operator-then-arguments :region :function-body :owner-function-syntax-id owner
                            :order [{:index 0 :core-node-id :parameter-entry-operator} {:index 1 :core-node-id :call}]}}
        definition-node (fn [id fn-id binding-id name name-id]
                          {:node-id id :core-form :def :children [fn-id] :resolved-binding-ids [binding-id]
                           :source (source id) :attributes {:name name :name-syntax-id name-id :visibility :private}
                           :evaluation {:kind :left-to-right :order [{:index 0 :core-node-id fn-id}]}})
        caller-node {:node-id :parameter-caller-fn :core-form :fn :children [:parameter-entry] :resolved-binding-ids []
                     :source (source owner) :attributes {:parameters [] :fixed-arity 0 :parameter-form-id :parameter-caller-parameters
                                                        :parameter-syntax-id :parameter-caller-parameters}
                     :evaluation {:kind :function-creation :order []}}
        leaf-nodes (mapv #(-> % (assoc :binding-context scope)
                              (assoc-in [:evaluation :region] :function-body)
                              (assoc-in [:evaluation :owner-function-syntax-id] owner)) (get-in argument [:core :nodes]))
        all-nodes (vec (concat (get-in base [:core :nodes])
                              [(definition-node :parameter-definition :parameter-fn :parameter-definition-binding 'tail-characters :parameter-definition-name)
                               entry-op] leaf-nodes [entry caller-node
                              (definition-node :parameter-caller-definition :parameter-caller-fn :parameter-caller-binding 'call-tail :parameter-caller-name)]))
        definitions [{:binding-id :parameter-definition-binding :name 'tail-characters :core-node-id :parameter-definition
                      :value-node-id :parameter-fn :syntax-id :parameter-definition}
                     {:binding-id :parameter-caller-binding :name 'call-tail :core-node-id :parameter-caller-definition
                      :value-node-id :parameter-caller-fn :syntax-id :parameter-caller-definition}]
        namespace (get-in base [:core :module :namespace])
        bindings (merge (:bindings base) (:bindings argument)
                        {:parameter-definition-binding {:binding-id :parameter-definition-binding :name 'tail-characters :namespace namespace
                                                        :kind :function :binding-class :namespace :definition-syntax-id :parameter-definition-name}
                         :parameter-caller-binding {:binding-id :parameter-caller-binding :name 'call-tail :namespace namespace
                                                    :kind :function :binding-class :namespace :definition-syntax-id :parameter-caller-name}})
        entry-call {:core-node-id :parameter-entry :operator-node-id :parameter-entry-operator :operator-binding-id :parameter-definition-binding
                    :argument-node-ids [:call] :ordered-evaluation-node-ids entry-children
                    :evaluation-order :operator-then-arguments :result-policy :call-result}
        entry-edge {:call-core-node-id :parameter-entry :caller-function-syntax-id owner :caller-function-core-node-id :parameter-caller-fn
                    :callee-binding-id :parameter-definition-binding :callee-definition-syntax-id :parameter-definition-name
                    :callee-function-syntax-id :parameter-function :callee-function-core-node-id :parameter-fn
                    :argument-core-node-ids [:call] :ordered-evaluation-node-ids entry-children
                    :evaluation-order :operator-then-arguments :classification :local-function}
        calls (conj (into (get-in base [:core :calls]) (get-in argument [:core :calls])) entry-call)
        edges (mapv #(assoc %2 :ordinal %1) (range)
                    (conj (into (get-in base [:core :call-edges])
                                (map #(assoc % :caller-function-syntax-id owner :caller-function-core-node-id :parameter-caller-fn)
                                     (get-in argument [:core :call-edges]))) entry-edge))
        forms (merge (:forms base) (update (:forms argument) :call assoc :parent-form-id :parameter-entry)
                     {:parameter-definition (form :parameter-definition :list nil nil [:parameter-def-operator :parameter-definition-name :parameter-function])
                      :parameter-def-operator (form :parameter-def-operator :symbol 'def :parameter-definition [])
                      :parameter-definition-name (form :parameter-definition-name :symbol 'tail-characters :parameter-definition [])
                      :parameter-caller-definition (form :parameter-caller-definition :list nil nil [:parameter-caller-def-operator :parameter-caller-name owner])
                      :parameter-caller-def-operator (form :parameter-caller-def-operator :symbol 'def :parameter-caller-definition [])
                      :parameter-caller-name (form :parameter-caller-name :symbol 'call-tail :parameter-caller-definition [])
                      owner (form owner :list (list 'fn [] (list 'tail-characters (list 'vec text)))
                                  :parameter-caller-definition [:parameter-caller-fn-operator :parameter-caller-parameters :parameter-entry])
                      :parameter-caller-fn-operator (form :parameter-caller-fn-operator :symbol 'fn owner [])
                      :parameter-caller-parameters (form :parameter-caller-parameters :vector [] owner [])
                      :parameter-entry (form :parameter-entry :list (list 'tail-characters (list 'vec text)) owner entry-children)
                      :parameter-entry-operator (form :parameter-entry-operator :symbol 'tail-characters :parameter-entry [])})
        forms (reduce #(assoc-in %1 [%2 :scope-id] scope) forms (keys (:forms argument)))
        core (assoc (:core base) :nodes all-nodes :function-records [record caller] :definitions definitions :calls calls :call-edges edges)]
    (assoc base :core core :nodes (into {} (map (juxt :node-id identity) all-nodes)) :forms forms :bindings bindings
           :record record :caller caller :types {} :initial-binding-types {})))

(defn- parameter-vector-count-slice-infer [{:keys [core nodes forms bindings]}]
  (let [functions (invoke-c7 'sh08-ft-function-skeletons [(:function-records core) (:module core)])
        products {:module (:module core) :calls (:calls core) :call-edges (:call-edges core)
                  :definitions (:definitions core) :function-index (into {} (map (juxt :function-syntax-id identity) (:function-records core)))
                  :recursion-components []}
        context {:ordering-core core :lookup-nodes nodes :lookup-forms (vec (vals forms)) :lookup-bindings (vec (vals bindings))
                 :shape-call-products products}]
    (invoke-c7 'sh08-ft-infer-acyclic-with-context
               [(:nodes core) nodes (get core :lexical-bindings []) (:definitions core) (:calls core) (:call-edges core) functions {} 32 context])))

(defn- parameter-vector-count-slice-products [text start]
  (let [input (parameter-vector-count-slice-caller-input text start)
        {:keys [core nodes bindings forms]} input
        inferred (parameter-vector-count-slice-infer input)
        facts {:module (:module core) :type-table (:type-table inferred)
               :function-type-table (invoke-c7 'sh08-ft-function-facts [(:function-types inferred) nodes (:module core)])
               :call-type-facts (invoke-c7 'sh08-ft-call-facts-with-context
                                          [(:calls core) (:call-edges core) nodes (:type-table inferred)
                                           (:function-types inferred) (:module core) {}])
               :constraint-ledger (:constraints inferred) :local-binding-facts []}
        request {:canonical-core-artifact core :b47-context {:authenticated-core-request {:forms (vec (vals forms))}}}]
    (assoc input :inference inferred :facts facts :request request)))

(deftest sh08-parameter-vector-count-slice-proof-development-kernel
  (let [input (parameter-vector-count-slice-input "0af" 1)
        derive (fn [{:keys [core node call edge nodes bindings types forms]} budget]
                 (invoke-c7 'sh08-vsl-derive [core node call edge nodes bindings types forms budget]))
        result (derive input 65536) descriptor (:descriptor result)
        established (assoc-in (assoc-in input [:types :slice-operator] descriptor) [:types :slice-call] (:type result))
        check (fn [{:keys [core node call edge nodes bindings types]} budget]
                (invoke-c7 'sh08-vsl-inferred-call [core node call edge nodes bindings types budget]))
        measured (check established 65536)
        witness (get-in descriptor [:bounds-proof :source-forms])]
    (is (= :accepted (:status result) (:status measured)))
    (is (= :immutable-parameter-vector (get-in descriptor [:bounds-proof :receiver :kind]) (get-in descriptor [:slice-policy :receiver])))
    (is (= 11 (count witness) (count (set (map :form-id witness)))))
    (is (= :same-immutable-vector-count (get-in descriptor [:bounds-proof :end :kind])))
    (is (not (contains? (get-in descriptor [:bounds-proof :receiver]) :return)))
    (is (not (contains? (get-in descriptor [:bounds-proof :receiver]) :function-type)))
    (is (= measured (check established (:work-count measured))))
    (is (= :vector-slice-work-limit (:reason (check established (dec (:work-count measured))))))
    (is (= result (derive input (:work-count result))))
    (is (= :vector-slice-work-limit (:reason (derive input (dec (:work-count result))))))
    (doseq [mutate [#(assoc-in % [:types :parameter-fn :parameters 0 :type] :gravity.type/unknown)
                    #(assoc-in % [:types :parameter-fn :parameters 0 :binding-id] :sibling)
                    #(assoc-in % [:types :parameter-fn :function-id] :sibling)
                    #(assoc-in % [:types :parameter-fn :parameters] [])
                    #(assoc-in % [:types :slice-ref] :gravity.type/vector)
                    #(assoc-in % [:bindings :slice-let-binding :mutability] :mutable)
                    #(assoc-in % [:core :mutations] [{:target-binding-id :slice-let-binding}])
                    #(assoc-in % [:forms :parameter-name :value] 'sibling)
                    #(assoc-in % [:forms :parameter-name :scope-id] :sibling)
                    #(assoc-in % [:forms :parameter-vector :child-form-ids] [])
                    #(assoc-in % [:forms :parameter-function :child-form-ids] [:parameter-fn-operator :parameter-vector :sibling])
                    #(assoc-in % [:nodes :slice-count-reference :attributes :binding-id] :sibling)
                    #(assoc-in % [:nodes :slice-count-reference :binding-context] :sibling)
                    #(assoc-in % [:nodes :slice-count-reference :evaluation :owner-function-syntax-id] :sibling)
                    #(assoc-in % [:nodes :slice-ref :attributes :definition-syntax-id] :sibling)
                    #(assoc-in % [:core :function-records 0 :body-core-node-id] :sibling)]]
      (is (= :rejected (:status (derive (mutate input) 65536)))))
    (doseq [path [[:bounds-proof :receiver :parameter-index] [:bounds-proof :receiver :parameter-type]
                  [:bounds-proof :receiver :binding :definition-syntax-id] [:bounds-proof :end :value]
                  [:bounds-proof :end :reference :node-id] [:slice-policy :receiver] [:invalidation]]]
      (is (= :rejected (:status (check (assoc-in established (into [:types :slice-operator] path) :forged) 65536))))))
  (doseq [[text start] [["0af" -1] ["0af" 4] ["" 1]]]
    (let [{:keys [core node call edge nodes bindings types forms]} (parameter-vector-count-slice-input text start)
          result (invoke-c7 'sh08-vsl-derive [core node call edge nodes bindings types forms 65536])]
      (is (= :rejected (:status result)))
      (is (= "STD3002" (:rule result)))))
  (let [{:keys [core node call edge nodes bindings types forms]} (parameter-vector-count-slice-input (apply str (repeat 1025 "a")) 0)]
    (is (= :rejected (:status (invoke-c7 'sh08-vsl-derive [core node call edge nodes bindings types forms 65536]))))))

(deftest sh08-parameter-vector-count-slice-caller-development-kernel
  (let [input (parameter-vector-count-slice-caller-input "0af" 1)
        result (parameter-vector-count-slice-infer input)]
    (is (= {} (:types input) (:initial-binding-types input)))
    (is (= :converged (:convergence-status result)) (pr-str (select-keys result [:convergence-status :diagnostics])))
    (is (= [] (:diagnostics result)))
    (is (= {:kind :gravity.type/vector :shape :literal :element-types (vec (repeat 3 :gravity.type/character))}
           (get-in result [:binding-types :slice-let-binding])))
    (is (= {:kind :gravity.type/vector :shape :literal :element-types (vec (repeat 2 :gravity.type/character))}
           (get-in result [:type-table :parameter-entry])))))

(deftest sh08-parameter-vector-count-slice-development-kernel
  (doseq [[text start] [["0af" 1] ["0af" 0] ["0" 1] ["" 0]]]
    (let [{:keys [core node call edge nodes bindings types forms count-result]}
          (parameter-vector-count-slice-input text start)
          result (invoke-c7 'sh08-vsl-derive [core node call edge nodes bindings types forms 65536])]
      (is (= :accepted (:status count-result)))
      (is (= :accepted (:status result)) (pr-str (select-keys result [:status :rule :reason])))
      (is (= {:kind :gravity.type/vector :shape :literal
              :element-types (vec (repeat (- (count text) start) :gravity.type/character))} (:type result)))))
  (let [{:keys [core node call edge nodes bindings types forms]} (parameter-vector-count-slice-input "" 1)
        result (invoke-c7 'sh08-vsl-derive [core node call edge nodes bindings types forms 65536])]
    (is (= :rejected (:status result)))
    (is (= :vector-slice-bounds-required (:reason result)))))

(defn- parameter-vector-count-slice-current-source-request [source-path]
  ;; Existing parent APIs; explicit current reader input, no substituted plan.
  (let [stage (fn [label operation]
                (println (pr-str {:parameter-source-stage label :event :begin}))
                (let [started (System/nanoTime) value (operation)]
                  (println (pr-str {:parameter-source-stage label :event :complete
                                    :elapsed-ms (quot (- (System/nanoTime) started) 1000000)})) value))
        text (slurp source-path)
        reader-path (path "bootstrap/gravity/src/gravity/bootstrap/reader.gravity")
        invocation {:reader-source-path reader-path
                    :authenticated-envelope-options {:source :development-current}}
        context (bootstrap/reader-project-context-for-source source-path)
        syntax (stage :c3 #(bootstrap/compiler-c3-syntax-source-artifact source-path text context nil nil reader-path invocation))
        expanded (stage :sh05 #(bootstrap/sh05-macro-artifact-from-c3-artifact source-path syntax invocation))
        resolved (stage :sh06 #(bootstrap/sh06-resolution-artifact-from-sh05-artifact
                                source-path expanded {:artifact :gravity/sh06-module-inputs :schema-version 1 :module-artifacts []}
                                reader-path invocation))
        core (stage :sh07 #(bootstrap/sh07-core-from-resolution-artifact resolved invocation))
        request (stage :c7-request #(function-request core invocation))]
    {:request request :core core :syntax syntax :expanded expanded :resolved resolved}))

(deftest sh08-parameter-vector-count-slice-current-source-composition
  ;; Separate genuine parent construction and fresh replay, never fake reports.
  (let [source-path (fixture-path "accepted" "local-runtime-parameter-vector-count-slice" ".gravity")
        {:keys [request]} (parameter-vector-count-slice-current-source-request source-path)
        result (invoke-c7 'sh08-function-type-core-artifact [request])]
    (is (= :accepted (:status result)) (pr-str (:diagnostics result)))
    (when (= :accepted (:status result))
      (require 'gravity.self-hosting.sh09-body-effect-test)
      (let [report (invoke-c7 'sh08-verify-function-type-result [request result])
            mutant (walk/postwalk-replace {:gravity.type/character :gravity.type/integer} result)
            core (:canonical-core-artifact request)
            bindings (into {} (map (juxt :binding-id identity) (get-in request [:b47-context :authenticated-core-request :binding-table])))
            nodes (into {} (map (juxt :node-id identity) (:nodes core)))
            records (into {} (map (juxt :function-syntax-id identity) (:function-records core)))
            functions (into {} (map (juxt :function-id identity) (:function-type-table mutant)))
            edge (first (filter #(= :local-function (:classification %)) (:call-edges core)))
            call (first (filter #(= (:call-core-node-id edge) (:core-node-id %)) (:calls core)))
            fact (first (filter #(= (:call-core-node-id edge) (:call-core-node-id %)) (:call-type-facts mutant)))
            c8 (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'leaf)
            forged-report (invoke-c7 'sh08-verify-function-type-result [request mutant])]
        (is (= :passed (:status report)))
        (is (not= result mutant))
        ;; Coherent function/caller table equality is conditional, not authority.
        (is (true? (c8 'body-function-joins-valid? core mutant bindings)))
        (is (true? (c8 'body-call-valid? edge call fact nodes functions records bindings (:type-table mutant))))
        (is (= :rejected (:status forged-report)))
        (is (= result (:expected forged-report)))
        (is (= mutant (:candidate forged-report)))))))

(deftest sh08-let-vector-slice-call-argument-current-source-composition
  ;; One distinct genuine current-reader input, followed by fresh C7 replay.
  (let [source-path (fixture-path "accepted" "local-runtime-let-vector-slice-call-argument" ".gravity")
        {:keys [request]} (parameter-vector-count-slice-current-source-request source-path)
        result (invoke-c7 'sh08-function-type-core-artifact [request])]
    (is (= :accepted (:status result)) (pr-str (:diagnostics result)))
    (when (= :accepted (:status result))
      (let [core (:canonical-core-artifact request)
            records (into {} (map (juxt :definition-name identity) (:function-records core)))
            callee (records 'tail-characters) caller (records 'main)
            edge (first (filter #(= :local-function (:classification %)) (:call-edges core)))
            argument-id (first (:argument-core-node-ids edge))
            call (first (filter #(= argument-id (:core-node-id %)) (:calls core)))
            descriptor (get-in result [:type-table (:operator-node-id call)])
            report (invoke-c7 'sh08-verify-function-type-result [request result])
            mutant (walk/postwalk-replace {:gravity.type/character :gravity.type/integer} result)
            rejected (invoke-c7 'sh08-verify-function-type-result [request mutant])]
        (is (= :passed (:status report)))
        (is (= (:function-syntax-id caller) (:caller-function-syntax-id edge)))
        (is (= (:function-syntax-id callee) (:callee-function-syntax-id edge)))
        (is (= :direct-local-function-slice-argument (get-in descriptor [:bounds-proof :receiver :body-consumer :kind])))
        (is (= argument-id (get-in descriptor [:bounds-proof :receiver :body-consumer :call :argument-node-ids 0])))
        (is (= 3 (count (get-in result [:type-table argument-id :element-types]))))
        (is (= (vec (repeat 3 :gravity.type/character)) (get-in result [:type-table argument-id :element-types])))
        (is (not= result mutant))
        (is (= :rejected (:status rejected)))
        (is (= result (:expected rejected)))
        (is (= mutant (:candidate rejected)))))))

(defn- let-vector-slice-call-input
  ([text start end] (let-vector-slice-call-input text start end 1))
  ([text start end callee-start]
   ;; One original local call body; expected callee types do not prove its arg.
   (let [base (parameter-vector-count-slice-caller-input text callee-start)
         outer :parameter-caller-scope body :argument-let-body bid :argument-local
         source #(hash-map :form-id % :syntax-id % :semantic-span nil :origin-chain [] :generated-origin nil)
         form (fn [id kind value parent children scope]
                {:form-id id :syntax-id id :source-span nil :origin-chain [] :generated-origin nil
                 :scope-id scope :kind kind :value value :parent-form-id parent :child-form-ids children})
         call-children [:argument-slice-operator :argument-slice-ref :argument-slice-start :argument-slice-end]
         evaluation (fn [kind ids] {:kind kind :owner-function-syntax-id :parameter-caller :region :function-body
                              :order (mapv #(hash-map :index %1 :core-node-id %2) (range) ids)})
         node (fn [id kind children attributes bindings]
                {:node-id id :core-form kind :children children :attributes attributes :resolved-binding-ids bindings
                 :source (source id) :binding-context body :evaluation (evaluation :value children)})
         slice-op (node :argument-slice-operator :reference []
                        {:symbol 'subvec :position :operator :binding-id :slice-binding :binding-class :core
                         :definition-syntax-id :slice-definition} [:slice-binding])
         reference (node :argument-slice-ref :reference []
                         {:symbol 'characters :position :expression :binding-id bid :binding-class :lexical
                          :definition-syntax-id :argument-name} [bid])
         literal (fn [id value] (node id :literal [] {:literal-kind :integer :value value} []))
         slice (assoc (node :argument-slice-call :call call-children
                            {:operator-child-index 0 :argument-count 3 :argument-child-indexes [1 2 3]
                             :evaluation-order :operator-then-arguments :dispatch :resolved-symbol-call} [:slice-binding])
                      :evaluation (evaluation :operator-then-arguments call-children))
         entry-children [:parameter-entry-operator :argument-slice-call]
         entry (-> (get-in base [:nodes :parameter-entry]) (assoc :children entry-children :binding-context body)
                   (assoc :evaluation (evaluation :operator-then-arguments entry-children)))
         entry-op (assoc (get-in base [:nodes :parameter-entry-operator]) :binding-context body)
         let-node {:node-id :argument-let :core-form :let :children [:call :parameter-entry] :resolved-binding-ids [bid]
                   :source (source :argument-let) :binding-context outer
