                      #(assoc-in % [:bindings :ordering-binding :package :version] "forged")
                      #(assoc-in % [:call :extra] true) #(assoc-in % [:edge :evaluation-order] :operand-first)
                      #(assoc-in % [:node :evaluation :order] [])
