            rejected (check changed-core changed-types 65536)]
        (is (= :rejected (:status own)))
        (is (= :rejected (:status rejected)))
        (is (= "C7-VERIFY" (get-in rejected [:diagnostics 0 :rule])))
        (is (= (+ prefix (:work-count own)) (:work-count rejected)))))))

