             (pr359-descriptor-emit 'p15-s23-mkeys-call-fact descriptor module) (pr359-descriptor-emit 'p15-s23-lq-call-fact descriptor module)))
      (is (= :direct-map-keys (:dispatch (pr359-descriptor-emit 'p15-s23-lq-call-fact descriptor module))))))
  (let [{:keys [core node call edge nodes bindings types forms]}
        ((pr359-descriptor-helper 'map-keys-input) :gravity.type/map)]
    (is (not= :accepted (:status (pr359-descriptor-c7 'sh08-mkeys-derive core node call edge nodes bindings types forms 65536))))))

(defn- pr359-prepend-helper [name] (ns-resolve 'gravity.self-hosting.sh08-function-call-type-test name))
(defn- pr359-prepend-c7 [name & args] ((pr359-prepend-helper 'invoke-c7) name (vec args)))
(defn- pr359-prepend-body [name & args]
  (require 'gravity.self-hosting.sh09-body-effect-test)
  (apply (ns-resolve 'gravity.self-hosting.sh09-body-effect-test 'leaf) name args))
(def ^:private pr359-prepend-emitter-plan
  (delay
    (let [path (bootstrap/p15-s23-stage2-compiler-artifact-source-path)
          emitter (:emitter (bootstrap/c-backend-stage2-plan-emitter-source-rule! path :jvm))]
      (bootstrap/p15-s23-stage2-compiler-artifact-plan emitter path (slurp path)))))
(defn- pr359-prepend-emit [name & args]
  (bootstrap/p15-s23-stage2-runtime-execute-function
   {:engine :prepend-premise-test} @pr359-prepend-emitter-plan name (vec args)))
(defn- pr359-prepend-literal [kind members] {:kind kind :shape :literal :element-types members})
(defn- pr359-prepend-homogeneous [kind element] {:kind kind :shape :homogeneous :element-type element})
(def ^:private pr359-prepend-cases
  (concat
   [[(pr359-prepend-literal :gravity.type/list []) :gravity.type/nil]
    [(pr359-prepend-literal :gravity.type/list [:gravity.type/bool :gravity.type/string]) :gravity.type/keyword]
    [:gravity.type/list :gravity.type/string]
    [(pr359-prepend-homogeneous :gravity.type/list :gravity.type/string) :gravity.type/string]
    [(pr359-prepend-homogeneous :gravity.type/list :gravity.type/string) :gravity.type/never]]
   (for [element [:gravity.type/string :gravity.type/keyword :gravity.type/symbol]
         [receiver value] [[(pr359-prepend-literal :gravity.type/set []) element]
                           [(pr359-prepend-literal :gravity.type/set [element]) element]
                           [(pr359-prepend-literal :gravity.type/set [element]) :gravity.type/never]]]
     [receiver value])
   (for [element [:gravity.type/string :gravity.type/symbol]]
     [(pr359-prepend-homogeneous :gravity.type/set element) element])))
(def ^:private pr359-prepend-obsolete [:operand-type-work :result-type-work :type-construction-work])

(defn- pr359-prepend-case-data [receiver value]
  (let [{:keys [core node call edge nodes bindings types forms module] :as input}
        ((pr359-prepend-helper 'list-prepend-input) receiver value)
        derived ((pr359-prepend-helper 'list-prepend-derived) input)
        descriptor (:descriptor derived)
        args [core node call edge nodes bindings types module]
        consumers [(pr359-prepend-body 'body-pl-finish
                         (apply pr359-prepend-body 'body-pl-source (conj args (pr359-prepend-body (quote body-pl-validate-types) [receiver value]))))
                   (pr359-prepend-emit 'p15-s23-pl-finish
                         (apply pr359-prepend-emit 'p15-s23-pl-source (conj args (pr359-prepend-emit (quote p15-s23-pl-validate-types) [receiver value]))))]
        context {:core core :nodes nodes :forms forms :bindings bindings
                 :types (assoc types :operator descriptor :call (:type derived))
                 :calls {:call call} :edges {:call edge} :call-order {:call 0}
                 :call-facts {:call (pr359-prepend-c7 'sh08-pl-call-fact descriptor module)}
                 :ledger [(pr359-prepend-c7 'sh08-pl-constraint descriptor)]
                 :locals {:arg0 'items :arg1 'value} :parameter-types types}]
    {:input input :derived derived :descriptor descriptor :consumers consumers :context context}))
(deftest pr359-prepend-complete-descriptors-and-typed-consumers
  (doseq [[receiver value] pr359-prepend-cases]
    (testing (str receiver " " value)
      (let [{:keys [derived descriptor consumers context]} (pr359-prepend-case-data receiver value)]
        (is (= :accepted (:status derived)))
        (is (every? #(= descriptor %) consumers))
        (is (every? #(not-any? (partial contains? %) pr359-prepend-obsolete) (cons descriptor consumers)))
        (is (= :complete (:status (pr359-prepend-emit 'p15-s23-typed-compile-node context :call 65536))))
        (is (= (:type derived) (:return descriptor) (:result-type descriptor)))
        (if (= value :gravity.type/never)
          (do (is (= :not-invoked (:application descriptor)))
              (is (= [] (:direct-effects descriptor)))
              (is (nil? (:result-extent descriptor))))
          (is (= [:memory/allocate] (:direct-effects descriptor))))))))

(deftest pr359-prepend-coherent-old-costs-and-forgeries-reject
  (doseq [[receiver value] pr359-prepend-cases]
    (let [{:keys [input descriptor context]} (pr359-prepend-case-data receiver value)
          compile #(pr359-prepend-emit 'p15-s23-typed-compile-node % :call 65536)
          coherent (fn [changed]
                     (-> context
                         (assoc-in [:types :operator] changed)
                         (assoc :call-facts {:call (pr359-prepend-c7 'sh08-pl-call-fact changed (:module input))}
                                :ledger [(pr359-prepend-c7 'sh08-pl-constraint changed)])))]
      (is (= :complete (:status (compile context))))
      (doseq [changed (concat (map #(assoc descriptor % 0) pr359-prepend-obsolete)
                             [(merge descriptor (zipmap pr359-prepend-obsolete [0 0 0]))
                              (assoc-in descriptor [:source :syntax-id] :forged)
                              (assoc descriptor :result-type :gravity.type/unknown)
                              (assoc descriptor :direct-effects [:io/write])])]
        (is (= :rejected (:status (compile (coherent changed))))))
      (doseq [change [#(assoc % :ledger [])
                      #(update % :ledger into (:ledger %))
                      #(assoc % :call-facts {})
                      #(assoc-in % [:bindings :ordering-binding :binding-class] :lexical)
                      #(assoc-in % [:forms :arg0 :parent-form-id] :stale)
                      #(assoc-in % [:types :arg0] :gravity.type/unknown)]]
        (is (= :rejected (:status (compile (change context)))))))))

(deftest pr359-prepend-late-invalid-and-opaque-types-reject-without-callbacks
  (let [callbacks (atom 0)
        opaque (proxy [Object] []
                 (hashCode [] (swap! callbacks inc) (throw (AssertionError. "opaque hash")))
                 (equals [_] (swap! callbacks inc) (throw (AssertionError. "opaque equality")))
                 (toString [] (swap! callbacks inc) (throw (AssertionError. "opaque formatting"))))]
    (doseq [[kind width index] [[:gravity.type/list 1023 1022] [:gravity.type/set 1024 1023]]
            invalid [:gravity.type/unknown opaque]]
      (let [receiver (pr359-prepend-literal kind (assoc (vec (repeat width :gravity.type/string)) index invalid))]
        (doseq [[invoke prefix] [[pr359-prepend-c7 "sh08-"] [pr359-prepend-body "body-"] [pr359-prepend-emit "p15-s23-"]]]
          (is (= :rejected (:status (invoke (symbol (str prefix "pl-validate-types")) [receiver :gravity.type/string])))))))
    (doseq [receiver [:gravity.type/set
                      (pr359-prepend-homogeneous :gravity.type/set :gravity.type/keyword)
                      (pr359-prepend-literal :gravity.type/vector [])]]
      (is (= :rejected (:status ((pr359-prepend-helper 'list-prepend-derived)
                                 ((pr359-prepend-helper 'list-prepend-input) receiver :gravity.type/string))))))
    (is (zero? @callbacks))))
(defn- recursive-validation-positional [children]
  {:kind :gravity.type/list :shape :literal :element-types children})

(defn- recursive-validation-nested [depth leaf]
  (loop [remaining depth value leaf]
    (if (zero? remaining) value
      (recur (dec remaining) (recursive-validation-positional [value])))))

(defn- recursive-validation-check [owner arguments]
  (case owner
    :C7 (return-premise-c7 'sh08-lc-validate-types arguments)
    :Effects (return-premise-effects 'body-lc-validate-types arguments)
    :emitter (return-premise-emit 'p15-s23-lc-validate-types arguments)))

(defn- recursive-validation-foreign-map [data callbacks]
  (proxy [clojure.lang.APersistentMap] []
    (count [] (swap! callbacks conj :count) (count data))
    (seq [] (swap! callbacks conj :seq) (seq data))
    (valAt
      ([key] (swap! callbacks conj :lookup) (get data key))
      ([key missing] (swap! callbacks conj :lookup) (get data key missing)))
    (containsKey [key] (swap! callbacks conj :contains) (contains? data key))
    (entryAt [key] (swap! callbacks conj :entry) (find data key))
    (assoc [_ _] (throw (AssertionError. "unexpected fixture assoc")))
    (without [_] (throw (AssertionError. "unexpected fixture without")))
    (empty [] (throw (AssertionError. "unexpected fixture empty")))
    (hashCode [] (swap! callbacks conj :hash) (throw (AssertionError. "foreign hash")))
    (equals [_] (swap! callbacks conj :equals) (throw (AssertionError. "foreign equality")))
    (toString [] (swap! callbacks conj :printing) (throw (AssertionError. "foreign printing")))))

(defn- recursive-validation-foreign-vector [callbacks]
  (proxy [clojure.lang.APersistentVector] []
    (count [] (swap! callbacks conj :count) 2)
    (nth
      ([_] (swap! callbacks conj :nth) :gravity.type/string)
      ([_ _] (swap! callbacks conj :nth) :gravity.type/string))
    (seq [] (swap! callbacks conj :seq) (seq [:gravity.type/string :gravity.type/bool]))
    (hashCode [] (swap! callbacks conj :hash) (throw (AssertionError. "foreign vector hash")))
    (equals [_] (swap! callbacks conj :equals) (throw (AssertionError. "foreign vector equality")))
    (toString [] (swap! callbacks conj :printing) (throw (AssertionError. "foreign vector printing")))))

(defn- recursive-validation-cyclic-type []
  (let [backing (object-array [:kind :gravity.type/list :shape :literal :element-types nil])
        value (clojure.lang.PersistentArrayMap. backing)]
    (aset backing 5 [value])
    value))

(defn- recursive-validation-cyclic-metadata []
  (let [backing (object-array [:self nil]) value (clojure.lang.PersistentArrayMap. backing)]
    (aset backing 1 value)
    value))

(defn- recursive-validation-link! [value field-name target]
  (let [field (.getDeclaredField (class value) field-name)]
    (when-not (.trySetAccessible field)
      (throw (ex-info "Native cycle fixture field is unavailable" {:field field-name})))
    (.set field value target)
    value))

(defn- recursive-validation-view [backing start end]
  (clojure.lang.APersistentVector$SubVector. nil backing start end))

(defn- recursive-validation-hidden-list [callbacks]
  (reify clojure.lang.IPersistentList
    (count [_] (swap! callbacks conj :count) (throw (AssertionError. "hidden List count")))
    (seq [_] (swap! callbacks conj :seq) (throw (AssertionError. "hidden List seq")))
    (cons [_ _] (throw (AssertionError. "hidden List cons")))
    (empty [_] (throw (AssertionError. "hidden List empty")))
    (equiv [_ _] (swap! callbacks conj :equals) (throw (AssertionError. "hidden List equality")))
    (peek [_] (swap! callbacks conj :peek) (throw (AssertionError. "hidden List peek")))
    (pop [_] (swap! callbacks conj :pop) (throw (AssertionError. "hidden List pop")))))

(deftest recursive-validation-logical-list-count-coherence
  ;; The existing native header uses public PersistentList.next(). At count
  ;; one its raw hidden tail is not logical DATA and stays inert. This does
  ;; not claim rejection of every reflectively corrupted raw JVM List layout.
  (let [callbacks (atom [])
        hidden-foreign (recursive-validation-hidden-list callbacks)
        one-foreign (list :gravity.type/string)
        one-cycle (list :gravity.type/string)
        malformed (mapv (fn [[values extent]]
                          (recursive-validation-link! values "_count" (Integer/valueOf extent)))
                        [[(list :gravity.type/string) 0]
                         [(list :gravity.type/string) -1]
                         [(list :gravity.type/string) 2]
                         [(list :gravity.type/string :gravity.type/bool) 3]])]
    (recursive-validation-link! one-foreign "_rest" hidden-foreign)
    (recursive-validation-link! one-cycle "_rest" one-cycle)
    (doseq [owner [:C7 :Effects :emitter]]
      (doseq [value malformed]
        (is (= :unsupported-arguments (:reason (recursive-validation-check owner value)))))
      (doseq [value [one-foreign one-cycle]]
        (is (= {:status :accepted} (recursive-validation-check owner value))))
      (is (empty? @callbacks)))))

(deftest recursive-validation-native-domain-and-inert-metadata
  (let [callbacks (atom []) metadata (recursive-validation-foreign-map {:opaque true} callbacks)
        shared (recursive-validation-positional [:gravity.type/string])
        hidden (proxy [Object] []
                 (hashCode [] (swap! callbacks conj :hash) (throw (AssertionError. "hidden hash")))
                 (equals [_] (swap! callbacks conj :equals) (throw (AssertionError. "hidden equality")))
                 (toString [] (swap! callbacks conj :printing) (throw (AssertionError. "hidden printing"))))
        backing [hidden :gravity.type/string :gravity.type/bool hidden]
        view (recursive-validation-view (recursive-validation-view backing 1 4) 0 2)
        cyclic-metadata (recursive-validation-cyclic-metadata)]
    (doseq [owner [:C7 :Effects :emitter]
            arguments
            [nil '() []
             (list :gravity.type/string :gravity.type/bool)
             (clojure.lang.Cons. :gravity.type/string (list :gravity.type/bool))
             view
             [(recursive-validation-positional view)]
             [(into clojure.lang.PersistentHashMap/EMPTY (recursive-validation-positional []))]
             [(into (sorted-map) (recursive-validation-positional []))]
             [(recursive-validation-positional [shared shared])]
             [(with-meta shared metadata)]
             (with-meta [:gravity.type/string] metadata)
             [(with-meta shared cyclic-metadata)]]]
      (is (= {:status :accepted}
             (recursive-validation-check owner arguments)) (str owner)))
    (is (identical? metadata (meta (with-meta shared metadata))))
    (is (identical? cyclic-metadata (:self cyclic-metadata)))
    (is (empty? @callbacks))))

(deftest recursive-validation-native-guards-precede-callbacks
  (let [callbacks (atom [])
        foreign-map (recursive-validation-foreign-map (recursive-validation-positional []) callbacks)
        foreign-vector (recursive-validation-foreign-vector callbacks)
        foreign-seq (reify clojure.lang.Seqable
                      (seq [_] (swap! callbacks conj :seq) (seq [:gravity.type/string])))
        opaque (proxy [Object] []
                 (hashCode [] (swap! callbacks conj :hash) (throw (AssertionError. "opaque hash")))
                 (equals [_] (swap! callbacks conj :equals) (throw (AssertionError. "opaque equality")))
                 (toString [] (swap! callbacks conj :printing) (throw (AssertionError. "opaque printing"))))
        bad-key (clojure.lang.PersistentArrayMap.
                 (object-array [:kind :gravity.type/list :shape :literal opaque []]))
        comparator (reify java.util.Comparator
                     (compare [_ left right] (swap! callbacks conj :compare) (compare left right)))
        sorted (into (sorted-map-by comparator) (recursive-validation-positional []))]
    (reset! callbacks [])
    (doseq [owner [:C7 :Effects :emitter]]
      (doseq [arguments [foreign-vector foreign-seq]]
        (is (= :unsupported-arguments (:reason (recursive-validation-check owner arguments)))))
      (doseq [type [foreign-map bad-key sorted opaque]]
        (is (= :unsupported-type (:reason (recursive-validation-check owner [type])))))
      (is (= :malformed-type
             (:reason (recursive-validation-check owner [(recursive-validation-positional foreign-vector)]))))
      (is (empty? @callbacks)))))

(deftest recursive-validation-view-links-and-spine-cycles
  (let [callbacks (atom []) foreign (recursive-validation-foreign-vector callbacks)
        backing [:gravity.type/string :gravity.type/bool]
        self-view (recursive-validation-view backing 0 1)
        left-view (recursive-validation-view backing 0 1)
        right-view (recursive-validation-view backing 0 1)
        cons-cycle (clojure.lang.Cons. :gravity.type/string nil)
        list-cycle (list :gravity.type/string :gravity.type/bool)]
    (recursive-validation-link! self-view "v" self-view)
    (recursive-validation-link! left-view "v" right-view)
    (recursive-validation-link! right-view "v" left-view)
    (recursive-validation-link! cons-cycle "_more" cons-cycle)
    (recursive-validation-link! list-cycle "_rest" list-cycle)
    (reset! callbacks [])
    (doseq [owner [:C7 :Effects :emitter]]
      (doseq [view [(recursive-validation-view backing -1 1)
                    (recursive-validation-view backing 1 0)
                    (recursive-validation-view backing 0 3)
                    (recursive-validation-view foreign 0 1)
                    self-view left-view]]
        (is (= :unsupported-arguments (:reason (recursive-validation-check owner view))))
        (is (= :malformed-type
               (:reason (recursive-validation-check owner [(recursive-validation-positional view)])))))
      (doseq [spine [cons-cycle list-cycle]]
        (is (= :cyclic-arguments (:reason (recursive-validation-check owner spine)))))
      (is (= :cyclic-type
             (:reason (recursive-validation-check owner [(recursive-validation-cyclic-type)]))))
      (is (empty? @callbacks)))))

(deftest recursive-validation-complete-types-beyond-old-structure-limits
  (let [callbacks (atom [])
        opaque (proxy [Object] []
                 (hashCode [] (swap! callbacks conj :hash) (throw (AssertionError. "opaque hash")))
                 (equals [_] (swap! callbacks conj :equals) (throw (AssertionError. "opaque equality")))
                 (toString [] (swap! callbacks conj :printing) (throw (AssertionError. "opaque printing"))))]
    (doseq [owner [:C7 :Effects :emitter]]
      (is (= {:status :accepted}
             (recursive-validation-check owner [(recursive-validation-nested 129 :gravity.type/string)])))
      (is (= {:status :accepted}
             (recursive-validation-check owner [(recursive-validation-positional (vec (repeat 1025 :gravity.type/string)))])))
      (doseq [leaf [:gravity.type/unknown opaque]]
        (is (= :unsupported-type
               (:reason (recursive-validation-check owner [(recursive-validation-nested 129 leaf)]))))
        (is (= :unsupported-type
               (:reason (recursive-validation-check owner
                         [(recursive-validation-positional (assoc (vec (repeat 1025 :gravity.type/string)) 1024 leaf))])))))
      (is (= :nested-never (:reason (recursive-validation-check owner [(recursive-validation-positional [:gravity.type/never])]))))
      (is (= {:status :accepted} (recursive-validation-check owner [:gravity.type/never])))
      (is (= :malformed-type (:reason (recursive-validation-check owner [{:kind :gravity.type/map :shape :literal :member-types [:gravity.type/string]}]))))
